package android.app; import java.util.*; public class AlarmManager {public static final int RTC_WAKEUP=0;public boolean exact=true,denyExact=false,fail=false;public int cancels=0,fallbacks=0;public Map<String,PendingIntent> alarms=new HashMap<>();public boolean canScheduleExactAlarms(){return exact;}public void cancel(PendingIntent p){cancels++;alarms.remove(p.intent.getAction());}public void setExactAndAllowWhileIdle(int type,long at,PendingIntent p){if(denyExact)throw new SecurityException();if(fail)throw new IllegalStateException();alarms.put(p.intent.getAction(),p);}public void setAndAllowWhileIdle(int type,long at,PendingIntent p){if(fail)throw new IllegalStateException();fallbacks++;alarms.put(p.intent.getAction(),p);}}
